import numpy as np, pandas as pd
train = pd.read_csv('train.csv')
feature_cols = [c for c in train.columns if c.startswith('x')]
X = train[feature_cols].values
y = train['target'].values.astype(float)

corrs = np.abs([np.corrcoef(X[:, i], y)[0, 1] for i in range(X.shape[1])])
corrs = np.nan_to_num(corrs)
sorted_idx = np.argsort(-corrs)

def make_features(X_base, top_idx, use_sq, use_int):
    parts = [X_base]
    if use_sq:
        parts.append(X_base[:, top_idx] ** 2)
    if use_int:
        for i in range(len(top_idx)):
            for j in range(i+1, len(top_idx)):
                parts.append((X_base[:, top_idx[i]] * X_base[:, top_idx[j]])[:, None])
    return np.column_stack(parts)

def ridge_loo(X, y, alpha):
    p = X.shape[1]
    XtX = X.T @ X + alpha * np.eye(p)
    w = np.linalg.solve(XtX, X.T @ y)
    H = X @ np.linalg.solve(XtX, X.T)
    h = np.diag(H)
    r = y - X @ w
    loo_r = r / (1 - h + 1e-12)
    return np.sqrt(np.mean(loo_r**2))

alphas = list(np.arange(1.0, 30.0, 1.0)) + [0.01, 0.1, 0.5, 50.0, 100.0, 200.0]
best_cv = float('inf')
for top_k in [5, 7, 10, 15]:
    top_idx = sorted_idx[:top_k]
    for use_sq in [True, False]:
        for use_int in [True, False]:
            if not use_sq and not use_int and top_k != 10:
                continue
            Xf = make_features(X, top_idx, use_sq, use_int)
            mu = Xf.mean(axis=0); sig = Xf.std(axis=0); sig[sig==0]=1
            Xs = (Xf - mu) / sig
            for alpha in alphas:
                cv = ridge_loo(Xs, y, alpha)
                if cv < best_cv:
                    best_cv = cv
                    print(f'k={top_k} sq={use_sq} int={use_int} alpha={alpha:.1f} cv={cv:.6f} nfeat={Xs.shape[1]}')
"
